import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

template <typename scalar_t>
__global__ void conv_transpose3d_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    const int batch, const int inC, const int outC,
    const int inD, const int inH, const int inW,
    const int outD, const int outH, const int outW,
    const int kD, const int kH, const int kW,
    const int sD, const int sH, const int sW,
    const int pD, const int pH, const int pW,
    const int groups)
{
    const long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long total = (long long)batch * outC * outD * outH * outW;
    if (idx >= total) return;

    const int ow = (int)(idx % outW);
    const int oh = (int)((idx / outW) % outH);
    const int od = (int)((idx / ((long long)outW * outH)) % outD);
    const int oc = (int)((idx / ((long long)outW * outH * outD)) % outC);
    const int b  = (int)(idx / ((long long)outW * outH * outD * outC));

    const int outC_per_group = outC / groups;
    const int inC_per_group = inC / groups;
    const int g = oc / outC_per_group;
    const int oc_local = oc - g * outC_per_group;

    scalar_t acc = (bias != nullptr) ? bias[oc] : (scalar_t)0;

    for (int ic = g * inC_per_group; ic < (g + 1) * inC_per_group; ++ic) {
        for (int kd = 0; kd < kD; ++kd) {
            const int td = od + pD - kd;
            if (td % sD != 0) continue;
            const int id = td / sD;
            if (id < 0 || id >= inD) continue;
            for (int kh = 0; kh < kH; ++kh) {
                const int th = oh + pH - kh;
                if (th % sH != 0) continue;
                const int ih = th / sH;
                if (ih < 0 || ih >= inH) continue;
                for (int kw = 0; kw < kW; ++kw) {
                    const int tw = ow + pW - kw;
                    if (tw % sW != 0) continue;
                    const int iw = tw / sW;
                    if (iw < 0 || iw >= inW) continue;
                    const long long in_idx =
                        ((((long long)b * inC + ic) * inD + id) * inH + ih) * inW + iw;
                    const long long w_idx =
                        ((((long long)ic * outC_per_group + oc_local) * kD + kd) * kH + kh) * kW + kw;
                    acc += input[in_idx] * weight[w_idx];
                }
            }
        }
    }
    output[idx] = acc;
}

torch::Tensor conv_transpose3d(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t output_padding, int64_t groups)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "input must be 5D (N, C, D, H, W)");

    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();

    const int batch = (int)input_c.size(0);
    const int inC   = (int)input_c.size(1);
    const int inD   = (int)input_c.size(2);
    const int inH   = (int)input_c.size(3);
    const int inW   = (int)input_c.size(4);

    const int outC  = (int)weight_c.size(1) * (int)groups;
    const int kD    = (int)weight_c.size(2);
    const int kH    = (int)weight_c.size(3);
    const int kW    = (int)weight_c.size(4);

    const int sD = (int)stride, sH = (int)stride, sW = (int)stride;
    const int pD = (int)padding, pH = (int)padding, pW = (int)padding;

    const int outD = (inD - 1) * sD - 2 * pD + kD + (int)output_padding;
    const int outH = (inH - 1) * sH - 2 * pH + kH + (int)output_padding;
    const int outW = (inW - 1) * sW - 2 * pW + kW + (int)output_padding;

    auto output = torch::empty({batch, outC, outD, outH, outW}, input_c.options());

    const long long total = (long long)batch * outC * outD * outH * outW;
    if (total == 0) return output;

    const int threads = 256;
    const long long blocks = (total + threads - 1) / threads;

    torch::Tensor bias_c;
    AT_DISPATCH_FLOATING_TYPES(input_c.scalar_type(), "conv_transpose3d_cuda", [&] {
        const scalar_t* bias_ptr = nullptr;
        if (bias.has_value() && bias.value().defined()) {
            bias_c = bias.value().contiguous();
            bias_ptr = bias_c.data_ptr<scalar_t>();
        }
        conv_transpose3d_kernel<scalar_t><<<(unsigned int)blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            input_c.data_ptr<scalar_t>(),
            weight_c.data_ptr<scalar_t>(),
            bias_ptr,
            output.data_ptr<scalar_t>(),
            batch, inC, outC,
            inD, inH, inW,
            outD, outH, outW,
            kD, kH, kW,
            sD, sH, sW,
            pD, pH, pW,
            (int)groups);
    });

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
