torch::Tensor conv_transpose3d(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t output_padding, int64_t groups);
"""

conv_transpose3d_ext = load_inline(
    name="conv_transpose3d_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution backed by a single custom CUDA kernel.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias)
        self.stride = self.conv_transpose3d.stride[0]
        self.padding = self.conv_transpose3d.padding[0]
        self.output_padding = self.conv_transpose3d.output_padding[0]
        self.groups = self.conv_transpose3d.groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose3d_ext.conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            self.conv_transpose3d.bias,
            self.stride,
            self.padding,
            self.output_padding,
            self.groups)

